-- 3) research_timeline_points: recompute status from actual snapshot completeness
--    (mirrors captureResearchTimelinePrices / saveResearchInitialSnapshots logic)
UPDATE research_timeline_points SET first_captured_at=COALESCE(first_captured_at,1788058504310), captured_at=COALESCE(captured_at,1788058504310), status=CASE WHEN (SELECT COUNT(*) FROM (SELECT provider,market FROM research_timeline_snapshots WHERE match_id='hkjc:50062944' AND stage='T5' GROUP BY provider,market HAVING COUNT(DISTINCT selection)>=2))>=6 THEN 'captured' ELSE 'partial' END, note=CASE WHEN (SELECT COUNT(*) FROM (SELECT provider,market FROM research_timeline_snapshots WHERE match_id='hkjc:50062944' AND stage='T5' GROUP BY provider,market HAVING COUNT(DISTINCT selection)>=2))>=6 THEN NULL ELSE (SELECT COUNT(*) FROM (SELECT provider,market FROM research_timeline_snapshots WHERE match_id='hkjc:50062944' AND stage='T5' GROUP BY provider,market HAVING COUNT(DISTINCT selection)>=2)) || '/6 provider-market pairs complete' END, updated_at=1788058504310 WHERE match_id='hkjc:50062944' AND stage='T5' AND status<>'captured';
